using Microsoft.EntityFrameworkCore;

// Cosmos DB provider: two breaking changes in EF Core 9
//
// 1. The default discriminator property changed from "Discriminator" to "$type".
//    Existing documents still carry "Discriminator", so we must opt back in
//    via HasDiscriminator() to keep reading them.
//
// 2. Synchronous LINQ queries (ToList, First, Single, etc.) are no longer
//    supported and throw InvalidOperationException.  All queries must use
//    their async counterparts.

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            databaseName: "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // Fix 1: preserve the legacy discriminator property name so existing
            //         documents with "Discriminator" continue to be read correctly.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }

    // Fix 2: all Cosmos queries must be async in EF Core 9.
    public async Task<List<Product>> GetProductsByCategoryAsync(string category)
    {
        return await Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task<Product?> GetProductByIdAsync(string id)
    {
        return await Products
            .FirstOrDefaultAsync(p => p.ExternalId == id);
    }
}

class Product
{
    public int Id { get; set; }
    public string ExternalId { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
}

